    public void surfaceChanged(SurfaceHolder holder, int format, int width, int height) {
        this.surfaceWidth = width;
        this.surfaceHeight = height;
        Rect rc = new Rect(0, 0, width, height);
        if (this.vkeypad != null) {
            this.vkeypad.resize(rc, this.displayMetrics);
        }
        int w = this.emulator.getVideoWidth();
        int h = this.emulator.getVideoHeight();
        int x = ((rc.left + rc.right) - w) / 2;
        int y = ((rc.top + rc.bottom) - h) / 2;
        if (x < 0) {
            x = 0;
        } else if (x > width - w) {
            x = width - w;
        }
        if (y < 0) {
            y = 0;
        } else if (y > height - h) {
            y = height - h;
        }
        this.emulator.setSurfaceRegion(width, height, x, y, w, h);
        this.surfaceRegion.left = x;
        this.surfaceRegion.top = y;
        this.surfaceRegion.right = x + w;
        this.surfaceRegion.bottom = y + h;
    }

