    private void makeBottomBottom(Rect bounds) {
        if (this.dpad.getWidth() + this.buttons.getWidth() > bounds.width()) {
            makeBottomTop(bounds);
            return;
        }
        this.dpad.move(bounds.left, bounds.bottom - this.dpad.getHeight());
        this.buttons.move(bounds.right - this.buttons.getWidth(), bounds.bottom - this.buttons.getHeight());
        if (this.extraButtons.isEnabled()) {
            this.extraButtons.move(bounds.right - this.extraButtons.getWidth(), bounds.bottom - ((this.buttons.getHeight() * 7) / 3));
        }
        int x = bounds.centerX() - (((this.buttons.getWidth() + this.selectStart.getWidth()) - this.dpad.getWidth()) / 2);
        if (x > this.dpad.getWidth() + bounds.left) {
            this.selectStart.move(x, bounds.bottom - this.selectStart.getHeight());
        } else {
            this.selectStart.move(bounds.centerX() - (this.selectStart.getWidth() / 2), bounds.top);
        }
        bounds.left += this.dpad.getVisibleWidth();
        bounds.right -= this.buttons.getVisibleWidth();
        bounds.bottom -= this.dpad.getVisibleHeight();
    }

    private void makeTopTop(Rect bounds) {
        if (this.dpad.getWidth() + this.buttons.getWidth() > bounds.width()) {
            makeBottomTop(bounds);
            return;
        }
        this.dpad.move(bounds.left, bounds.top);
        int y = bounds.top;
        if (this.extraButtons.isEnabled()) {
            this.extraButtons.move(bounds.right - this.extraButtons.getWidth(), y);
            y += (this.buttons.getHeight() * 4) / 3;
        }
        this.buttons.move(bounds.right - this.buttons.getWidth(), y);
        this.selectStart.move(bounds.centerX() - (this.selectStart.getWidth() / 2), bounds.bottom - this.selectStart.getHeight());
        bounds.left += this.dpad.getVisibleWidth();
        bounds.right -= this.buttons.getVisibleWidth();
        bounds.top += this.dpad.getVisibleHeight();
    }

    private void makeTopBottom(Rect bounds) {
        this.dpad.move(bounds.left, bounds.top);
        this.buttons.move(bounds.right - this.buttons.getWidth(), bounds.bottom - this.buttons.getHeight());
        if (this.extraButtons.isEnabled()) {
            this.extraButtons.move(bounds.right - this.extraButtons.getWidth(), bounds.bottom - ((this.buttons.getHeight() * 7) / 3));
        }
        int x = bounds.centerX() - ((this.buttons.getWidth() + this.selectStart.getWidth()) / 2);
