    private void reposition(Rect bounds, SharedPreferences prefs) {
        if (this.view.getWidth() > this.view.getHeight()) {
            bounds.left += this.marginX;
            bounds.right -= this.marginX;
        } else {
            bounds.top += this.marginY;
            bounds.bottom -= this.marginY;
        }
        String layout = prefs.getString("vkeypadLayout", DefaultPreferences.getVKeypadLayout(this.context));
        if ("top_bottom".equals(layout)) {
            makeBottomBottom(bounds);
            return;
        }
        if ("bottom_top".equals(layout)) {
